206	/// Composite types declarations using angle brackets syntax can be arbitrary
207	/// nested such that the following declaration is possible:
208	///      `ARRAY<ARRAY<INT>>`
209	/// But the tokenizer recognizes the `>>` as a ShiftRight token.
210	/// We work around that limitation when parsing a data type by accepting
211	/// either a `>` or `>>` token in such cases, remembering which variant we
212	/// matched.
213	/// In the latter case having matched a `>>`, the parent type will not look to
214	/// match its closing `>` as a result since that will have taken place at the
215	/// child type.
216	///
217	/// See [Parser::parse_data_type] for details
218	struct MatchedTrailingBracket(bool);
219	
220	impl From<bool> for MatchedTrailingBracket {
221	    fn from(value: bool) -> Self {
222	        Self(value)
223	    }
224	}
