295	/// A SQL Parser
296	///
297	/// This struct is the main entry point for parsing SQL queries.
298	///
299	/// # Functionality:
300	/// * Parsing SQL: see examples on [`Parser::new`] and [`Parser::parse_sql`]
301	/// * Controlling recursion: See [`Parser::with_recursion_limit`]
302	/// * Controlling parser options: See [`Parser::with_options`]
303	/// * Providing your own tokens: See [`Parser::with_tokens`]
304	///
305	/// # Internals
306	///
307	/// The parser uses a [`Tokenizer`] to tokenize the input SQL string into a
308	/// `Vec` of [`TokenWithSpan`]s and maintains an `index` to the current token
309	/// being processed. The token vec may contain multiple SQL statements.
310	///
311	/// * The "current" token is the token at `index - 1`
312	/// * The "next" token is the token at `index`
313	/// * The "previous" token is the token at `index - 2`
314	///
315	/// If `index` is equal to the length of the token stream, the 'next' token is
316	/// [`Token::EOF`].
317	///
318	/// For example, the SQL string "SELECT * FROM foo" will be tokenized into
319	/// following tokens:
320	/// ```text
321	///  [
322	///    "SELECT", // token index 0
323	///    " ",      // whitespace
324	///    "*",
325	///    " ",
326	///    "FROM",
327	///    " ",
328	///    "foo"
329	///   ]
330	/// ```
331	///
332	///
333	pub struct Parser<'a> {
334	    /// The tokens
335	    tokens: Vec<TokenWithSpan>,
336	    /// The index of the first unprocessed token in [`Parser::tokens`].
337	    index: usize,
338	    /// The current state of the parser.
339	    state: ParserState,
340	    /// The SQL dialect to use.
341	    dialect: &'a dyn Dialect,
342	    /// Additional options that allow you to mix & match behavior
343	    /// otherwise constrained to certain dialects (e.g. trailing
344	    /// commas) and/or format of parse (e.g. unescaping).
345	    options: ParserOptions,
346	    /// Ensures the stack does not overflow by limiting recursion depth.
347	    recursion_counter: RecursionCounter,
348	    /// Cached failures from `parse_prefix` calls that returned `Err`. See
349	    /// [`Parser::parse_prefix`] for the 2^N patterns this guards.
350	    failed_prefix_positions: BTreeMap<usize, ExprPrefixError>,
351	    /// Cached failures from the speculative reserved-word prefix arm. See
352	    /// [`Parser::parse_prefix`] for the 2^N patterns this guards.
353	    failed_reserved_word_prefix_positions: BTreeMap<usize, ExprPrefixError>,
354	    /// Cached failures from the speculative derived-table arm of
355	    /// `parse_table_factor`. See [`Parser::parse_table_factor`] for the 2^N
356	    /// pattern this guards.
357	    failed_derived_table_factor_positions: BTreeSet<usize>,
358	    /// Cached failures from the speculative subquery arm of [`Parser::parse_in`],
359	    /// which `IN` lists nested in a leading subquery would otherwise retry at
360	    /// every level, taking 2^N time. Maps the arm's start to where a parsed
361	    /// query lacked its `)`.
362	    failed_in_subquery_positions: BTreeMap<usize, Option<usize>>,
363	}
