365	/// Copy marker for a [`ParserError`] cached by the `parse_prefix` failure
366	/// memoization, so the caches hold no strings.
367	#[derive(Debug, Clone, Copy)]
368	enum ExprPrefixError {
369	    RecursionLimitExceeded,
370	    Err,
371	}
