373	impl From<&ParserError> for ExprPrefixError {
374	    fn from(e: &ParserError) -> Self {
375	        match e {
376	            ParserError::RecursionLimitExceeded => Self::RecursionLimitExceeded,
377	            _ => Self::Err,
378	        }
379	    }
380	}
