```rust
/// Returns the [`Location`] just past the last character of `sql`,
/// using the same line/column rules as the [`Tokenizer`]: lines and
/// columns are 1-based, columns count Unicode code points, a tab
/// occupies a single column, and a lone `\r`, a lone `\n`, or a
/// `\r\n` pair each count as a single newline.
fn end_of_input_location(sql: &str) -> Location {
    let mut line = 1;
    let mut column = 1;
    let mut prev_was_cr = false;
    for ch in sql.chars() {
        match ch {
            '\r' => {
                line += 1;
                column = 1;
            }
            '\n' => {
                if !prev_was_cr {
                    line += 1;
                }
                column = 1;
            }
            _ => {
                column += 1;
            }
        }
        prev_was_cr = ch == '\r';
    }
    Location { line, column }
}
```

