/// Returns the EOF token to use when reading past the end of `tokens`.
///
/// The span is a zero-width range at the end of the input: if the
/// token stream explicitly ends with an EOF token, its start location
/// is used; otherwise the end location of the last token (which may be
/// trailing whitespace) is used. If no location is available (an empty
/// token stream, or tokens without locations), the span is empty.
fn eof_token_for(tokens: &[TokenWithSpan]) -> TokenWithSpan {
    let location = match tokens.last() {
        Some(last) if last.token == Token::EOF => last.span.start,
        Some(last) => last.span.end,
        None => Location::empty(),
    };
    let span = if location.line == 0 {
        Span::empty()
    } else {
        Span::new(location, location)
    };
    TokenWithSpan::new(Token::EOF, span)
}
