use sqlparser::dialect::{GenericDialect, MySqlDialect};
use sqlparser::parser::Parser;

fn main() {
    let d = GenericDialect {};
    // 1. basic EOF location
    let e = Parser::new(&d).try_with_sql("SELECT -").unwrap().parse_statements().unwrap_err();
    println!("1: {e}");
    assert_eq!(e.to_string(), "sql parser error: Expected: an expression, found: EOF at Line: 1, Column: 9");

    // 2. trailing \r\n, comment, unicode, trailing space
    let sql = "SELECT 1 +\r\n/*\u{4e2d}*/ ";
    let e = Parser::new(&d).try_with_sql(sql).unwrap().parse_statements().unwrap_err();
    println!("2: {e}");
    assert!(e.to_string().ends_with("found: EOF at Line: 2, Column: 7"), "{e}");

    // 3. empty sql
    let mut p = Parser::new(&d).try_with_sql("").unwrap();
    let t = p.next_token();
    println!("3: {:?} {:?}", t.token, t.span);
    assert_eq!(format!("{:?}", t.span), "Span(Location(1,1)..Location(1,1))");

    // 4. whitespace/comment-only sql parses to empty list
    let r = Parser::new(&d).try_with_sql("  -- hi\n /* x */ ").unwrap().parse_statements().unwrap();
    assert!(r.is_empty());
    println!("4: ok");

    // 5. MySQL executable comment at end
    let my = MySqlDialect {};
    let e = Parser::new(&my).try_with_sql("SELECT 1 + /*!*/").unwrap().parse_statements().unwrap_err();
    println!("5: {e}");
    assert!(e.to_string().ends_with("found: EOF at Line: 1, Column: 17"), "{e}");
    let e = Parser::new(&my).try_with_sql("SELECT 1 + /*!50110 KEY_BLOCK_SIZE = 1024*/").unwrap().parse_statements().unwrap_err();
    println!("5b: {e}");
    assert!(e.to_string().ends_with("Column: 44"), "{e}");

    // 6. with_tokens (no locations) -> empty span, no location in error
    use sqlparser::tokenizer::{Token, Word};
    let tokens = vec![Token::Word(Word { value: "SELECT".into(), quote_style: None, keyword: sqlparser::keywords::Keyword::SELECT })];
    let e = Parser::new(&d).with_tokens(tokens).parse_statements().unwrap_err();
    println!("6: {e}");
    assert_eq!(e.to_string(), "sql parser error: Expected: an expression, found: EOF");

    // 7. repeated reads at EOF are stable; prev/next
    let mut p = Parser::new(&d).try_with_sql("SELECT 1 ").unwrap();
    while !matches!(p.next_token().token, Token::EOF) {}
    let a = p.next_token();
    let b = p.next_token();
    assert_eq!(a.span, b.span);
    p.prev_token();
    let c = p.next_token();
    assert_eq!(a.span, c.span);
    println!("7: {:?} ok", a.span);

    // 8. reuse parser with new input
    let mut p = Parser::new(&d).try_with_sql("SELECT -").unwrap();
    let _ = p.parse_statements();
    let mut p = p.try_with_sql("SELECT 1").unwrap();
    let t = loop { let t = p.next_token(); if matches!(t.token, Token::EOF) { break t } };
    assert_eq!(format!("{:?}", t.span), "Span(Location(1,9)..Location(1,9))");
    println!("8: ok");

    // 9. missing rparen / keyword
    let e = Parser::new(&d).try_with_sql("SELECT (1").unwrap().parse_statements().unwrap_err();
    println!("9: {e}");
    assert!(e.to_string().contains("found: EOF at Line: 1, Column: 10"), "{e}");

    // 10. peek_tokens / peek_tokens_with_location at EOF
    let p = Parser::new(&d).try_with_sql("SELECT 1\n").unwrap();
    let toks: [sqlparser::tokenizer::TokenWithSpan; 2] = p.peek_tokens_with_location();
    let _ = toks;
    println!("10: ok");

    println!("ALL OK");
}
