pub fn one_statement_parses_to(&self, sql: &str, canonical: &str) -> Statement {
    let mut statements = self.parse_sql_statements(sql).expect(sql);
    assert_eq!(statements.len(), 1);
    if !canonical.is_empty() && sql != canonical {
