use sqlparser::dialect::GenericDialect;
use sqlparser::keywords::Keyword;
use sqlparser::parser::Parser;
use sqlparser::tokenizer::{Location, Span, Token, TokenWithSpan, Whitespace, Word};

fn loc(l: u64, c: u64) -> Location { Location::new(l, c) }

fn main() {
    let d = GenericDialect {};
    let select = || TokenWithSpan::new(
        Token::Word(Word { value: "SELECT".into(), quote_style: None, keyword: Keyword::SELECT }),
        Span::new(loc(1, 1), loc(1, 7)),
    );

    // 1. explicit EOF at end -> its span.start is the EOF location
    let p = Parser::new(&d).with_tokens_with_locations(vec![
        select(),
        TokenWithSpan::new(Token::EOF, Span::new(loc(3, 5), loc(3, 5))),
    ]);
    let t = p.token_at(5);
    assert_eq!(t.token, Token::EOF);
    assert_eq!(t.span, Span::new(loc(3, 5), loc(3, 5)), "explicit EOF");
    println!("1 ok: {:?}", t.span);

    // 2. trailing whitespace token participates
    let p = Parser::new(&d).with_tokens_with_locations(vec![
        select(),
        TokenWithSpan::new(Token::Whitespace(Whitespace::Space), Span::new(loc(1, 7), loc(1, 9))),
    ]);
    let t = p.token_at(9);
    assert_eq!(t.span, Span::new(loc(1, 9), loc(1, 9)), "trailing ws");
    println!("2 ok: {:?}", t.span);

    // 3. empty token list -> empty span
    let p = Parser::new(&d).with_tokens_with_locations(vec![]);
    assert_eq!(p.token_at(0).span, Span::empty());
    println!("3 ok");

    // 4. tokens with empty spans -> empty span
    let p = Parser::new(&d).with_tokens_with_locations(vec![TokenWithSpan::wrap(select().token.clone())]);
    assert_eq!(p.token_at(3).span, Span::empty());
    println!("4 ok");

    // 5. explicit EOF with empty span -> empty span
    let p = Parser::new(&d).with_tokens_with_locations(vec![select(), TokenWithSpan::wrap(Token::EOF)]);
    assert_eq!(p.token_at(7).span, Span::empty());
    println!("5 ok");

    // 6. consistency across read APIs (skip-ws, no-skip, single, multi)
    let mut p = Parser::new(&d).try_with_sql("SELECT 1  ").unwrap();
    while !matches!(p.next_token().token, Token::EOF) {}
    let expected = Span::new(loc(1, 11), loc(1, 11));
    assert_eq!(p.peek_token().span, expected);
    assert_eq!(p.peek_token_ref().span, expected);
    assert_eq!(p.peek_nth_token(3).span, expected);
    assert_eq!(p.peek_nth_token_ref(2).span, expected);
    assert_eq!(p.peek_token_no_skip().span, expected);
    assert_eq!(p.peek_nth_token_no_skip(4).span, expected);
    assert_eq!(p.token_at(100).span, expected);
    assert_eq!(p.get_current_token().span, expected);
    assert_eq!(p.get_next_token().span, expected);
    let multi: [TokenWithSpan; 3] = p.peek_tokens_with_location();
    assert!(multi.iter().all(|t| t.span == expected));
    let multi_ref: [&TokenWithSpan; 2] = p.peek_tokens_ref();
    assert!(multi_ref.iter().all(|t| t.span == expected));
    assert_eq!(p.next_token().span, expected);
    println!("6 ok");

    // 7. zero-width span
    assert_eq!(expected.start, expected.end);
    println!("ALL OK");
}
